CREATE TABLE IF NOT EXISTS students(id SERIAL PRIMARY KEY, full_name TEXT NOT NULL, roll_number TEXT UNIQUE NOT NULL, section TEXT, department TEXT, subject TEXT, faculty_name TEXT, avatar_url TEXT, resume_key TEXT, instagram_url TEXT, github_url TEXT, linkedin_url TEXT, email TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_users(id SERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS resources(id SERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT, category TEXT, file_key TEXT, original_filename TEXT, mime_type TEXT, file_size BIGINT, uploaded_by INT REFERENCES admin_users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_resources_category ON resources(category);
CREATE TABLE IF NOT EXISTS modules(id SERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT, module_number INT, resource_id INT REFERENCES resources(id) ON DELETE SET NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS lab_experiments(id SERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT, experiment_number INT, resource_id INT REFERENCES resources(id) ON DELETE SET NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS tools(id SERIAL PRIMARY KEY, name TEXT NOT NULL, description TEXT, category TEXT, icon TEXT, documentation_url TEXT, resource_id INT REFERENCES resources(id) ON DELETE SET NULL, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
